UPDATE t_query_key_type
SET status = #{status}, version = version + 1, updated_by = #{updatedBy}, update_time = #{updateTime}
WHERE key_type_id = #{row.keyTypeId} AND version = #{row.version} AND status = #{row.status}

UPDATE t_query_key_type
SET sort_no = #{sortNo}, version = version + 1, updated_by = #{updatedBy}, update_time = #{updateTime}
WHERE key_type_id = #{row.keyTypeId} AND version = #{row.version}
